// Runtime for the recompiled PowerPC code: CPU state, memory and
// helpers used by the C++ generated by tools/recomp.py.
#pragma once
#include <atomic>
#include <cmath>
#include <cstdint>
#include <cstring>
#ifdef _WIN32
#include <intrin.h>   // _BitScanReverse: MSVC knows it without this, clang for Windows does not
#endif

union FPR {
    double d;
    uint64_t u;
};

struct Ctx {
    uint32_t r[32];
    FPR f[32];
    uint32_t cr;    // PowerPC bit 0 = bit 31 here
    uint32_t xer;   // SO=bit31, OV=bit30, CA=bit29
    uint32_t lr, ctr, msr, fpscr;
    uint32_t srr0, srr1;
    uint32_t sr[16];
    uint32_t spr[1024];
    uint32_t reserve;
    uint64_t cycles;       // approximate cycles (1 per instruction)
    uint64_t next_event;   // next runtime event (frame, interrupt)
    uint32_t pc_hint;      // last known position, for the profiler
};

extern Ctx g_ctx;

// ---- Memory (big-endian, like the original hardware) ----
uint8_t rt_rd8_slow(uint32_t a);
uint16_t rt_rd16_slow(uint32_t a);
uint32_t rt_rd32_slow(uint32_t a);
void rt_wr8_slow(uint32_t a, uint8_t v);
void rt_wr16_slow(uint32_t a, uint16_t v);
void rt_wr32_slow(uint32_t a, uint32_t v);

extern uint8_t* g_ram;
constexpr uint32_t RAM_SIZE = 8u * 1024 * 1024;

static inline uint32_t bswap32(uint32_t v) { return _byteswap_ulong(v); }
static inline uint16_t bswap16(uint16_t v) { return _byteswap_ushort(v); }

static inline uint8_t rd8(uint32_t a) {
    return a < RAM_SIZE ? g_ram[a] : rt_rd8_slow(a);
}
static inline uint16_t rd16(uint32_t a) {
    if (a < RAM_SIZE - 1) { uint16_t v; memcpy(&v, g_ram + a, 2); return bswap16(v); }
    return rt_rd16_slow(a);
}
static inline uint32_t rd32(uint32_t a) {
    if (a < RAM_SIZE - 3) { uint32_t v; memcpy(&v, g_ram + a, 4); return bswap32(v); }
    return rt_rd32_slow(a);
}
static inline uint64_t rd64(uint32_t a) {
    return (uint64_t(rd32(a)) << 32) | rd32(a + 4);
}
static inline void wr8(uint32_t a, uint8_t v) {
    if (a < RAM_SIZE) g_ram[a] = v; else rt_wr8_slow(a, v);
}
static inline void wr16(uint32_t a, uint16_t v) {
    if (a < RAM_SIZE - 1) { v = bswap16(v); memcpy(g_ram + a, &v, 2); } else rt_wr16_slow(a, v);
}
static inline void wr32(uint32_t a, uint32_t v) {
    if (a < RAM_SIZE - 3) { v = bswap32(v); memcpy(g_ram + a, &v, 4); } else rt_wr32_slow(a, v);
}
static inline void wr64(uint32_t a, uint64_t v) {
    wr32(a, uint32_t(v >> 32));
    wr32(a + 4, uint32_t(v));
}

// ---- Indirect calls, events and special cases ----
void rt_call(Ctx& c, uint32_t addr);          // bctrl / blrl / tables
void rt_event(Ctx& c);                        // frame, interrupts
void rt_bad(Ctx& c, uint32_t addr);           // invalid instruction
void rt_sc(Ctx& c, uint32_t addr);            // sc
uint32_t rt_text_region(uint32_t country);    // country seen by the text-language choice
bool rt_subtitles_off();                      // subtitles of the voice lines hidden
void rt_projected(uint32_t lr, uint32_t vec, uint32_t px, uint32_t py);   // fn_0003BE44 returned (aim assist)
void rt_gun_aimed(uint32_t vec, uint32_t player);   // fn_0000CBF0 made the aim (wide 3D view: beyond 4:3)
uint32_t rt_mfspr(Ctx& c, uint32_t spr);      // SPRs with side effects (DEC, TB)
void rt_mtspr(Ctx& c, uint32_t spr, uint32_t v);
void rt_mtmsr(Ctx& c, uint32_t v);
void rt_lswi(Ctx& c, uint32_t ea, int rd, int nb);
void rt_stswi(Ctx& c, uint32_t ea, int rs, int nb);

// Debugging: --trace ADDR prints the registers on entry to that function
extern uint8_t g_trace_bits[512];   // fast filter for --trace and the hooks
// Makes ENTER call rt_trace on entry to fn (its bit in g_trace_bits)
inline void rt_hook_function(uint32_t fn) { g_trace_bits[(fn >> 5) & 511] |= uint8_t(1 << ((fn >> 2) & 7)); }
void rt_trace(Ctx& c, uint32_t fn);
extern uint32_t g_recent_fn[64];
extern uint32_t g_recent_idx;
void rt_print_recent();
void rt_dma_copy(uint32_t dst, uint32_t src, uint32_t n);   // 53C810 Memory Move
#define ENTER(pc) do { g_recent_fn[g_recent_idx++ & 63] = (pc); \
    if (g_trace_bits[((pc) >> 5) & 511] & (1 << (((pc) >> 2) & 7))) rt_trace(c, pc); POLL(pc); } while (0)

#define POLL(pc) do { c.pc_hint = (pc); if (c.cycles >= c.next_event) rt_event(c); } while (0)
extern bool g_fast_idle;   // idle loops (tools/recomp.py IDLE_LOOPS) skip to the next event
// Game states (boss mode) are saved and put back from the vblank wait loop
extern std::atomic<int> g_state_op;
void rt_state_point(Ctx& c);
#define IDLE(pc) do { if (g_state_op.load(std::memory_order_relaxed)) rt_state_point(c); \
    if (g_fast_idle && c.cycles < c.next_event) c.cycles = c.next_event; POLL(pc); } while (0)

// ---- Condition registers ----
static inline uint32_t crbit(const Ctx& c, int bi) { return (c.cr >> (31 - bi)) & 1; }
static inline void setcrbit(Ctx& c, int bi, uint32_t v) {
    c.cr = (c.cr & ~(1u << (31 - bi))) | ((v & 1) << (31 - bi));
}
static inline void setcrf(Ctx& c, int fld, uint32_t nib) {
    int sh = 28 - 4 * fld;
    c.cr = (c.cr & ~(0xFu << sh)) | (nib << sh);
}
static inline uint32_t so(const Ctx& c) { return c.xer >> 31; }
static inline void cmps(Ctx& c, int fld, int32_t a, int32_t b) {
    setcrf(c, fld, (a < b ? 8 : a > b ? 4 : 2) | so(c));
}
static inline void cmpu(Ctx& c, int fld, uint32_t a, uint32_t b) {
    setcrf(c, fld, (a < b ? 8 : a > b ? 4 : 2) | so(c));
}
static inline void cr0(Ctx& c, uint32_t v) { cmps(c, 0, int32_t(v), 0); }
static inline uint32_t ca(const Ctx& c) { return (c.xer >> 29) & 1; }
static inline void setca(Ctx& c, uint32_t v) { c.xer = (c.xer & ~(1u << 29)) | ((v & 1) << 29); }

// Add with carry: returns the result and updates CA
static inline uint32_t addca(Ctx& c, uint32_t a, uint32_t b, uint32_t cin) {
    uint64_t t = uint64_t(a) + b + cin;
    setca(c, uint32_t(t >> 32));
    return uint32_t(t);
}

static inline uint32_t rotl(uint32_t v, uint32_t n) { n &= 31; return n ? (v << n) | (v >> (32 - n)) : v; }
static inline uint32_t clz32(uint32_t v) { unsigned long i; return _BitScanReverse(&i, v) ? 31 - i : 32; }

static inline uint32_t sraw(Ctx& c, uint32_t s, uint32_t n) {
    n &= 0x3F;
    int32_t v = int32_t(s);
    if (n > 31) { setca(c, v < 0); return uint32_t(v >> 31); }
    uint32_t r = uint32_t(v >> n);
    setca(c, v < 0 && n && (s & ((1u << n) - 1)) != 0);
    return r;
}

static inline uint32_t divw(int32_t a, int32_t b) {
    if (b == 0 || (a == INT32_MIN && b == -1)) return a < 0 ? 0xFFFFFFFF : 0;
    return uint32_t(a / b);
}
static inline uint32_t divwu(uint32_t a, uint32_t b) { return b ? a / b : 0; }

// ---- Floating point ----
static inline double f2d(uint32_t bits) { float f; memcpy(&f, &bits, 4); return f; }
static inline uint32_t d2fbits(double d) { float f = float(d); uint32_t u; memcpy(&u, &f, 4); return u; }
static inline double rs(double d) { return double(float(d)); }

static inline uint64_t fctiw(double d, bool trunc) {
    double r = trunc ? std::trunc(d) : std::nearbyint(d);
    int32_t i;
    if (std::isnan(r)) i = INT32_MIN;
    else if (r >= 2147483647.0) i = INT32_MAX;
    else if (r <= -2147483648.0) i = INT32_MIN;
    else i = int32_t(r);
    return 0xFFF8000000000000ull | uint32_t(i);
}
static inline void fcmp(Ctx& c, int fld, double a, double b) {
    uint32_t n = std::isnan(a) || std::isnan(b) ? 1 : a < b ? 8 : a > b ? 4 : 2;
    setcrf(c, fld, n);
    c.fpscr = (c.fpscr & ~0xF000u) | (n << 12);
}
static inline double frsqrte(double d) { return 1.0 / std::sqrt(d); }
